/api/file?key=monitoring.text:
window: {from: "19:00", to: "01:00"}
refresh: 300
newrelic: {enabled: true, account: 4100777, api: "https://newrelic.atlas.example"}
splunk: {enabled: true, api: "https://splunk.atlas.example", query: 'index=atlas env=$env$ ERROR | stats count BY exception', known: [KnownWarmupException]}
stages:
  TEST: {app: atlas-test_orders, env: test}
  UAT: {app: atlas-uat_orders, env: int}
  PROD: {app: atlas-prod_orders, env: prod}
versioncheck:
  enabled: true
  version_regex: 'Build version:\s*(\d+\.\d+\.\d+)'
  nok_regex: '<li>status:\s*(?:<[^>]*>\s*)*(?!UP\b)\w+'
  stages:
    DEV: "https://status.atlas.example/DEV"
    TEST: "https://status.atlas.example/TEST"
    UAT: "https://status.atlas.example/UAT"
    EDGE: "https://status.atlas.example/EDGE"
    EDGE-01: "https://status.atlas.example/EDGE-01"
    EDGE-02: "https://status.atlas.example/EDGE-02"
    EDGE-03: "https://status.atlas.example/EDGE-03"
    EDGE-RC: "https://status.atlas.example/EDGE-RC"
    EDGE-PILOT: "https://status.atlas.example/EDGE-PILOT"
    EDGE-STAGE: "https://status.atlas.example/EDGE-STAGE"
    PROD: "https://status.atlas.example/PROD"
    SHADOW: "https://status.atlas.example/SHADOW"
blockers: {enabled: true, jql: 'priority = Blocker AND resolution = Unresolved', max: 20}
map: {enabled: true, stages: [LOAD-A, LOAD-B, TEST, UAT, PROD], apps: [orders, routing]}
perf:
  nights: 7
  envs:
    LOAD-A: {branch: main, app: atlas-load-a_orders, versioncheck: "https://status.atlas.example/LOAD-A"}
    LOAD-B: {branch: service pack, app: atlas-load-b_orders, versioncheck: "https://status.atlas.example/LOAD-B"}
uat_tests:
  app: atlas-uat_orders
  tests: [{date: 2026-11-17, from: "20:00", to: "22:00"}]
errors: {enabled: true}

